#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> K(n);
    vector<vector<pair<int,int>>> orig(n);
    int totalCells = 0;

    for(int i = 0; i < n; i++){
        cin >> K[i];
        orig[i].resize(K[i]);
        for(int j = 0; j < K[i]; j++){
            cin >> orig[i][j].first >> orig[i][j].second;
        }
        totalCells += K[i];
    }

    // Transform: first flip (f=1 means reflect over x: x -> -x), then rotate r times 90° CCW
    // Rotate CCW: (x,y) -> (-y, x)
    auto transform = [](const vector<pair<int,int>>& cells, int f, int r) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x, y] : cells){
            int nx = x, ny = y;
            if(f) nx = -nx; // flip
            for(int q = 0; q < r; q++){
                int tmp = nx;
                nx = -ny;
                ny = tmp;
            }
            res.push_back({nx, ny});
        }
        // Normalize to non-negative
        int minx = INT_MAX, miny = INT_MAX;
        for(auto [x,y] : res){ minx = min(minx, x); miny = min(miny, y); }
        for(auto& [x,y] : res){ x -= minx; y -= miny; }
        return res;
    };

    struct Ori {
        vector<pair<int,int>> cells;
        int w, h, f, r;
    };

    vector<vector<Ori>> allOris(n);
    for(int i = 0; i < n; i++){
        set<vector<pair<int,int>>> seen;
        for(int f = 0; f < 2; f++){
            for(int r = 0; r < 4; r++){
                auto tc = transform(orig[i], f, r);
                sort(tc.begin(), tc.end());
                if(seen.insert(tc).second){
                    int w = 0, h = 0;
                    for(auto [x,y] : tc){ w = max(w, x+1); h = max(h, y+1); }
                    allOris[i].push_back({tc, w, h, f, r});
                }
            }
        }
    }

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return K[a] > K[b]; });

    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now() - startTime).count();
    };

    long long bestArea = LLONG_MAX;
    int bestW = 0, bestH = 0;
    struct Pl { int x, y, r, f; };
    vector<Pl> bestPl(n);
    bool found = false;

    double sq = sqrt((double)totalCells);
    for(int W = max(1,(int)(sq*0.5)); W <= (int)(sq*3)+10; W++){
        if(elapsed() > 9.0 && found) break;
        int maxH = max(300, totalCells/max(1,W) + 50);
        if((long long)W*maxH > 4000000) maxH = 4000000/W;
        if(maxH < 10) continue;
        vector<int> hmap(W, 0);
        vector<vector<bool>> grid(W, vector<bool>(maxH, false));
        vector<Pl> pl(n);
        int curH = 0; bool fail = false;
        for(int idx = 0; idx < n && !fail; idx++){
            if(elapsed() > 9.5 && found){ fail=true; break; }
            int pi = order[idx];
            int bs = INT_MAX, bx=-1, by=-1, bo=-1;
            for(int oi = 0; oi < (int)allOris[pi].size(); oi++){
                auto& o = allOris[pi][oi];
                if(o.w > W) continue;
                for(int x = 0; x <= W - o.w; x++){
                    int my = 0;
                    for(auto [cx,cy] : o.cells) my = max(my, hmap[x+cx]-cy);
                    if(my<0) my=0;
                    int top = 0;
                    for(auto [cx,cy] : o.cells) top = max(top, my+cy+1);
                    if(top > maxH) continue;
                    bool ok = true;
                    for(auto [cx,cy] : o.cells) if(grid[x+cx][my+cy]){ok=false;break;}
                    if(ok){
                        int sc = top*10000+x;
                        if(sc < bs){ bs=sc; bx=x; by=my; bo=oi; }
                    }
                }
            }
            if(bx==-1){ fail=true; break; }
            auto& o = allOris[pi][bo];
            for(auto [cx,cy] : o.cells){
                grid[bx+cx][by+cy]=true;
                hmap[bx+cx]=max(hmap[bx+cx],by+cy+1);
                curH=max(curH,by+cy+1);
            }
            pl[pi]={bx,by,o.r,o.f};
        }
        if(fail) continue;
        long long area = (long long)W*curH;
        if(area < bestArea){ bestArea=area; bestW=W; bestH=curH; bestPl=pl; found=true; }
    }

    if(!found){
        bestW = totalCells; bestH = 1;
        int cx = 0;
        for(int i = 0; i < n; i++){
            bestPl[i]={cx,0,0,0};
            cx += allOris[i][0].w;
        }
        bestW = cx; bestH = allOris[0][0].h;
        for(int i=0;i<n;i++) bestH=max(bestH,allOris[i][0].h);
    }

    cout << bestW << " " << bestH << "\n";
    for(int i = 0; i < n; i++){
        cout << bestPl[i].x << " " << bestPl[i].y << " " << bestPl[i].r << " " << bestPl[i].f << "\n";
    }
}
